DATE = datetime.date(2030, 1, 2)
CALCULATED_AT = datetime.datetime(2030, 1, 2, 15, 30, tzinfo=datetime.timezone.utc)


def _structure():
    return OptionStructure(
        (OptionLeg("SPY", "call", 100.0, datetime.date(2030, 3, 3)),),
        100000.0,
        14,
    )


def _assembly(state=CandidateState.WATCH, missing=("artifacts pending",)):
    return assemble_candidate_research_record(
        "assembly-001",
        "candidate-001",
        state,
        "caller supplied state",
        DATE,
        "testable convexity hypothesis",
        _structure(),
        None,
        None,
        None,
        None,
        None,
        None,
        None,
        (
            ClassifiedEvidence(
                "evidence-1",
                EvidenceKind.CALCULATED_METRIC,
                EvidenceImpact.SUPPORTS,
                "Synthetic reviewed evidence",
                "synthetic fixture",
                "fixture-v1",
            ),
        ),
        ("contrary evidence",),
        missing,
        ("false-positive channel",),
        None,
        ("what changes the conclusion?",),
        CALCULATED_AT,
    )


def _qualitative(identifier, category, trigger, authority=pm.PositionManagementAuthority.CALLER):
    return pm.QualitativePositionManagementCondition(
        identifier, category, trigger, authority, " source note ", " rationale "
    )


def _watch_condition():
    return _qualitative(
        "review_event",
        pm.PositionManagementCategory.REASSESSMENT,
        pm.PositionManagementQualitativeTrigger.EVENT_WINDOW_SHIFTS,
    )


def _watch_result(identifier="plan-001", calculated_at=None):
    assembly = _assembly()
    calculated_at = calculated_at or assembly.lineage.calculated_at + datetime.timedelta(seconds=1)
    return pm.create_position_management_plan(
        identifier, assembly, [_watch_condition()], calculated_at
    )


def _full_result(identifier="plan-full"):
    from test_candidate_assembly import assemble_artifacts, complete_artifacts

    assembly = assemble_artifacts(complete_artifacts())
    conditions = [
        _qualitative(
            "monetize",
            pm.PositionManagementCategory.MONETIZATION,
            pm.PositionManagementQualitativeTrigger.EVENT_BECOMES_PUBLIC,
        ),
        _watch_condition(),
        _qualitative(
            "exit_event",
            pm.PositionManagementCategory.EXIT,
            pm.PositionManagementQualitativeTrigger.EVENT_CANCELLED,
        ),
    ]
    return pm.create_position_management_plan(
        identifier,
        assembly,
        conditions,
        assembly.lineage.calculated_at + datetime.timedelta(seconds=1),
    )


def _two_leg_assembly():
    from test_candidate_assembly import assemble_artifacts
    from test_market_data_transformations import (
        make_scenario_valuation_result,
        make_selection,
        transform,
    )
    import convexity_hunter.market_data_transformations as transformations
    from test_risk_assessment import complete_assumptions

    arguments = make_scenario_valuation_result(
        ("call", "put"), return_arguments=True
    )
    costs = arguments[1]
    tail = arguments[2]
    scenario = transformations.transform_scenario_valuation(*arguments)
    _, _, volatility = transformations._verify_tail_pricing_result(
        tail.records, tail.lineage
    )
    selection = make_selection(
        costs.record.structure,
        bid=("1.00", "2.00"),
        ask=("1.40", "2.60"),
    )[0]
    liquidity = transform(costs.record.structure, selection)
    expiration = transformations.transform_expiration_payoff_thresholds(
        "expiration-two-leg",
        costs,
        CALCULATED_AT + datetime.timedelta(seconds=11),
    )
    affordability = risk_assessment.assess_structure_affordability(
        "affordability-two-leg",
        costs,
        complete_assumptions(),
        CALCULATED_AT + datetime.timedelta(seconds=12),
    )
    return assemble_artifacts((
        volatility,
        tail,
        liquidity,
        costs,
        scenario,
        expiration,
        affordability,
    ))


def _forged_lineage(lineage, **changes):
    forged = object.__new__(CalculationLineage)
    for field in dataclasses.fields(CalculationLineage):
        value = changes.get(field.name, getattr(lineage, field.name))
        object.__setattr__(forged, field.name, value)
    return forged


def _forged_assembly(assembly, **changes):
    forged = object.__new__(CandidateResearchRecordAssemblyResult)
    for field in dataclasses.fields(CandidateResearchRecordAssemblyResult):
        value = changes.get(field.name, getattr(assembly, field.name))
        object.__setattr__(forged, field.name, value)
    return forged


def _forged_dataclass(value, **changes):
    forged = object.__new__(type(value))
    for field in dataclasses.fields(value):
        object.__setattr__(
            forged,
            field.name,
            changes.get(field.name, getattr(value, field.name)),
        )
    return forged


def _test_tagged_map(value):
    if type(value) is not dict or set(value) != {"$map"}:
        raise AssertionError("expected one tagged map")
    pairs = value["$map"]
    if type(pairs) is not list or any(
        type(pair) is not list or len(pair) != 2 or type(pair[0]) is not str
        for pair in pairs
    ):
        raise AssertionError("expected canonical map pairs")
    keys = [pair[0] for pair in pairs]
    if len(set(keys)) != len(keys):
        raise AssertionError("expected unique map keys")
    return {pair[0]: pair[1] for pair in pairs}


def _test_tagged_list(value):
    if type(value) is not dict or set(value) != {"$list"}:
        raise AssertionError("expected one tagged list")
    if type(value["$list"]) is not list:
        raise AssertionError("expected list payload")
    return value["$list"]


